// Obtener todos los datos de las hojas
const areasData = $('Read Areas').all();
const modulosData = $('Read Modulos').all();
const topicsData = $('Read Topics').all();
const recursosData = $('Read Recursos').all();

// Extraer JSON de cada fuente
const areas = areasData.map(item => item.json);
const modulos = modulosData.map(item => item.json);
const topics = topicsData.map(item => item.json);
const recursos = recursosData.map(item => item.json);

// Función para limpiar y normalizar datos
const cleanData = (arr) => {
  return arr.map(item => {
    const cleaned = {};
    for (const [key, value] of Object.entries(item)) {
      if (value === 'TRUE' || value === 'true') cleaned[key] = true;
      else if (value === 'FALSE' || value === 'false') cleaned[key] = false;
      else if (value === '' || value === null || value === undefined) cleaned[key] = null;
      else if (!isNaN(value) && value !== '') cleaned[key] = Number(value);
      else cleaned[key] = value;
    }
    return cleaned;
  });
};

const cleanedAreas = cleanData(areas);
const cleanedModulos = cleanData(modulos);
const cleanedTopics = cleanData(topics);
const cleanedRecursos = cleanData(recursos);

// Crear el objeto de sincronización completo
const syncPayload = {
  sync_type: 'full',
  timestamp: new Date().toISOString(),
  action: 'sync_all',
  source: 'google_sheets',
  spreadsheet_id: '15Zpa7kkkGf6PeEIADg1Y4uusS-G-mtms6p_i2WS-k-8',
  data: {
    areas: cleanedAreas,
    modulos: cleanedModulos,
    topics: cleanedTopics,
    recursos: cleanedRecursos
  },
  statistics: {
    areas_count: cleanedAreas.length,
    modulos_count: cleanedModulos.length,
    topics_count: cleanedTopics.length,
    recursos_count: cleanedRecursos.length,
    total_records: cleanedAreas.length + cleanedModulos.length + cleanedTopics.length + cleanedRecursos.length
  }
};

return [{ json: syncPayload }];

const raw = $json.body ?? $json;
const body = Array.isArray(raw) ? raw[0] : raw;

const empleado_id = (body.employee_id || '').toString().trim();
if (!empleado_id) throw new Error('Falta empleado_id');

return [{
  json: {
    empleado_id,
    reason: (body.reason || 'Sin motivo').toString().trim(),
    deleted_at: new Date().toISOString(),
    token_expires: new Date(Date.now() - 60000).toISOString(),
    estado_global: 'INACTIVO',
    enabled: 'false'
  }
}];

const target = $node['Code - Normalize Delete Payload'].json.empleado_id;
const rows = $items('Google Sheets - Read Empleados').map(i => i.json);
const found = rows.find(r => (r.empleado_id || r.employee_id || '') === target);

return [{ json: { exists: !!found, email: found?.email || '', nombre: found?.nombre || '', area: found?.area || '', ...$node['Code - Normalize Delete Payload'].json } }];

const query = $node["Webhook - Employee Progress"].json.query || {};
const empleado_id = (query.empleado_id || "").toString().trim();

if (!empleado_id) {
  return [{ json: { ok: false, error: "Falta empleado_id" } }];
}

const rows = $items("Google Sheets - Read Empleado_Modulo_Progreso").map(i => i.json);
const bitacora = $items("Google Sheets - Read Bitacora").map(i => i.json);

const modulos = rows
  .filter(r => (r.employee_id || r.empleado_id || "").toString().trim() === empleado_id)
  .map(r => ({
    modulo_id: r.modulo_id || "",
    modulo_nombre: r.modulo_nombre || "",
    area_id: (r.area_id || "").toString().toUpperCase(),
    status: (r.status || "NO_INICIADO").toString().toUpperCase(),
    progreso_pct: Number(r.progreso_pct || 0),
    topics_total: Number(r.topics_total || 0),
    topics_completados: Number(r.topics_completados || 0),
    quiz_score_avg: Number(r.quiz_score_avg || 0),
    last_activity_at: r.last_activity_at || "",
    next_review_at: r.next_review_at || ""
  }));

const modulos_total = modulos.length;
const modulos_completados = modulos.filter(m => m.status === "COMPLETADO").length;
const modulos_en_progreso = modulos.filter(m => m.status === "EN_PROGRESO").length;
const modulos_no_iniciados = modulos.filter(m => m.status === "NO_INICIADO").length;

const progreso_global_pct = modulos_total
  ? Math.round(modulos.reduce((acc, m) => acc + (Number(m.progreso_pct) || 0), 0) / modulos_total)
  : 0;

const employeeEvents = bitacora.filter(e => (e.employee_id || e.empleado_id || "") === empleado_id);
employeeEvents.sort((a,b) => new Date(b.timestamp || 0) - new Date(a.timestamp || 0));
const last_activity_at = employeeEvents[0]?.timestamp || modulos.map(m => m.last_activity_at).filter(Boolean).sort().reverse()[0] || "";

return [{
  json: {
    ok: true,
    empleado_id,
    resumen: {
      progreso_global_pct,
      modulos_total,
      modulos_completados,
      modulos_en_progreso,
      modulos_no_iniciados,
      last_activity_at
    },
    modulos: modulos.sort((a,b) => (a.modulo_nombre || "").localeCompare(b.modulo_nombre || ""))
  }
}];

const query = $node["Webhook - Admin Modules Progress"].json.query || {};
const areaFilter = (query.area || "").toString().trim().toUpperCase();
const cohortFilter = (query.cohort || "").toString().trim();

let rows = $items("Google Sheets - Read Empleado_Modulo_Progreso1").map(i => i.json);

if (areaFilter) {
  rows = rows.filter(r => (r.area_id || "").toString().toUpperCase() === areaFilter);
}
if (cohortFilter) {
  rows = rows.filter(r => (r.cohort || "") === cohortFilter);
}

const byModule = new Map();

for (const r of rows) {
  const modulo_id = (r.modulo_id || "").toString().trim();
  if (!modulo_id) continue;

  if (!byModule.has(modulo_id)) {
    byModule.set(modulo_id, {
      modulo_id,
      modulo_nombre: r.modulo_nombre || "",
      area_id: (r.area_id || "").toString().toUpperCase(),
      empleados_asignados: 0,
      progreso_sum: 0,
      completados: 0,
      en_progreso: 0,
      no_iniciados: 0,
      en_riesgo: 0
    });
  }

  const m = byModule.get(modulo_id);
  const pct = Number(r.progreso_pct || 0);
  const status = (r.status || "NO_INICIADO").toString().toUpperCase();

  m.empleados_asignados += 1;
  m.progreso_sum += pct;

  if (status === "COMPLETADO") m.completados += 1;
  else if (status === "EN_PROGRESO") m.en_progreso += 1;
  else if (status === "EN_RIESGO") m.en_riesgo += 1;
  else m.no_iniciados += 1;
}

const data = Array.from(byModule.values()).map(m => ({
  modulo_id: m.modulo_id,
  modulo_nombre: m.modulo_nombre,
  area_id: m.area_id,
  empleados_asignados: m.empleados_asignados,
  promedio_progreso_pct: m.empleados_asignados ? Math.round(m.progreso_sum / m.empleados_asignados) : 0,
  completados: m.completados,
  en_progreso: m.en_progreso,
  no_iniciados: m.no_iniciados,
  en_riesgo: m.en_riesgo
}))
.sort((a,b) => b.promedio_progreso_pct - a.promedio_progreso_pct);

return [{ json: { ok: true, data } }];

