const emailIn    = ($node["Code - Parse + Token"].json.email    || "").trim().toLowerCase();
const passwordIn = ($node["Code - Parse + Token"].json.password || "").toString();
const nowMs      = Number($node["Code - Parse + Token"].json.now_ms);
const newToken         = $node["Code - Parse + Token"].json.new_token;
const newTokenExpires  = $node["Code - Parse + Token"].json.new_token_expires;

const empleados = $items("Google Sheets - Read Empleados3").map(i => i.json);

const emp = empleados.find(e =>
  (e.email || "").toString().trim().toLowerCase() === emailIn
);
if (!emp) {
