    newTokenExpires,
    emp: {
      empleado_id:            emp.empleado_id || "",
      nombre:                 emp.nombre      || "",
      email:                  emailIn,
      rol:                    emp.rol         || "",
      area:                   emp.area        || "",
      estado_global:          estado,
      meta_certificacion_pct: emp.meta_certificacion_pct || 85,
      must_change_password:   emp.must_change_password,
      auth_token:             emp.auth_token    || "",
      token_expires:          emp.token_expires || ""
    }
  }
}];

const item = $input.first();
const raw = item.json.body ?? item.json;
const body = Array.isArray(raw) ? raw[0] : raw;

const email = (body.email || '').toString().trim().toLowerCase();
if (!email) throw new Error('Falta email');

// areas puede venir como array o como string "A, B"
let newAreas = [];
if (Array.isArray(body.areas) && body.areas.length) {
  newAreas = body.areas.map(a => String(a).trim()).filter(Boolean);
} else {
  newAreas = String(body.area || '').split(',').map(a => a.trim()).filter(Boolean);
}

// unique + sort
newAreas = Array.from(new Set(newAreas)).sort();

const patch = {
  empleado_id: body.empleado_id || body.employee_id,
  nombre: body.nombre,
  rol: body.rol,
  area: body.area ?? newAreas.join(', '),
  fecha_inicio: body.fecha_inicio,
  estado_global: body.estado_global,
  manager_email: body.manager_email,
  evaluacion_url: body.evaluacion_url,
  meta_certificacion_pct: body.meta_certificacion_pct,
  last_activity_at: body.last_activity_at ?? new Date().toISOString(),
};

// limpia vacíos
for (const k of Object.keys(patch)) {
  if (patch[k] === undefined || patch[k] === null || patch[k] === '') delete patch[k];
}

return [{
  json: { email, newAreas, patch }
}];

// INPUT: viene de "Read Empleado Actual" (1 item)
// Además lee el output de "Normalize Patch"

const current = $input.first().json;
const norm = $items("Normalize Patch", 0, 0)[0].json;

// helpers
const toAreas = (v) => {
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  return String(v || "").split(",").map(x => x.trim()).filter(Boolean);
};
const uniqSort = (arr) => Array.from(new Set(arr)).sort();

// Áreas actuales (hoja)
const oldAreas = uniqSort(toAreas(current.area));
const area_actual = String(current.area || "").trim(); // <- tal cual hoja (ej: "OPERACIONES")

// Áreas entrantes (request)
const incomingAreas = uniqSort(
  toAreas(
    (norm.newAreas && norm.newAreas.length)
      ? norm.newAreas
      : (norm.patch?.area ?? norm.area ?? "")
  )
);

// ✅ newAreas = SOLO las áreas que entran y NO están en las actuales
const oldSet = new Set(oldAreas);
const newAreas = incomingAreas.filter(a => !oldSet.has(a));

// Si también quieres detectar removidas:
const incomingSet = new Set(incomingAreas);
const removedAreas = oldAreas.filter(a => !incomingSet.has(a));

// Flags
const added_changed = newAreas.length > 0;
const removed_changed = removedAreas.length > 0;

// Tú decides la regla del cambio:
// - Solo si se agregan áreas:
const area_changed = added_changed;
// - O si cambia el set completo (agrega o quita), usa:
// const area_changed = added_changed || removed_changed;

const empleado_id = current.empleado_id || norm.patch?.empleado_id;
if (!empleado_id) throw new Error("No se encontró empleado_id");

const merged = {
  // claves
  empleado_id,
  email: (current.email || norm.email || "").toLowerCase(),

  // ✅ área actual desde la hoja
  area_actual,

  // campos editables (merge)
  nombre: norm.patch?.nombre ?? current.nombre,
  rol: norm.patch?.rol ?? current.rol,

  // Esto sigue guardando lo que venga (string con comas si envías así)
  area: (norm.patch?.area ?? current.area),

  fecha_inicio: norm.patch?.fecha_inicio ?? current.fecha_inicio,
  estado_global: String(norm.patch?.estado_global ?? current.estado_global ?? "ACTIVO").trim().toUpperCase(),
  manager_email: String(norm.patch?.manager_email ?? current.manager_email ?? "").trim().toLowerCase(),
  evaluacion_url: String(norm.patch?.evaluacion_url ?? current.evaluacion_url ?? "").trim(),
  meta_certificacion_pct: norm.patch?.meta_certificacion_pct ?? current.meta_certificacion_pct,
  last_activity_at: norm.patch?.last_activity_at ?? current.last_activity_at ?? new Date().toISOString(),

  // extras
  incomingAreas,     // todo lo que llega
  newAreas,          // SOLO las áreas nuevas (diferentes al/los actuales)
  removedAreas,      // SOLO las removidas (si aplica)
  added_changed,
  removed_changed,
  area_changed
};

return [{ json: merged }];

// Recalcula progreso del MÓDULO usando Empleado_Recursos_Progreso (filas del módulo)
// INPUT: items vienen desde "Read Empleado_Recursos_Progreso1" (returnAllMatches)
// WEBHOOK: datos del evento vienen de "Webhook - Update Topic Progress"

const ev = $items('Webhook - Update Topic Progress', 0, 0)[0].json.body || {};

// filas del módulo (cada item es un recurso del módulo)
const rows = $input.all().map(i => i.json);

// Totales / completados (por recursos)
const total = rows.length;
const completados = rows.filter(r => String(r.status || '').toUpperCase() === 'COMPLETADO').length;

// ✅ progreso_modulo (antes progreso_area)
const progreso_modulo = total ? Math.round((completados / total) * 100) : 0;

// ✅ status_modulo (antes status)
let status_modulo = 'NO_INICIADO';
if (progreso_modulo >= 100) status_modulo = 'COMPLETADO';
else if (progreso_modulo > 0) status_modulo = 'EN_PROGRESO';

// last_activity_at (máxima fecha encontrada en recursos, fallback al evento / ahora)
const last_activity_at =
  rows.map(r => r.last_activity_at).filter(Boolean).sort().reverse()[0]
  || ev.last_activity_at
  || new Date().toISOString();

// regla simple de “EN_RIESGO” (opcional)
const now = new Date();
const last = last_activity_at ? new Date(last_activity_at) : null;
let en_riesgo = false;

if (
  status_modulo === 'EN_PROGRESO' &&
  last &&
  (now - last) / (1000 * 60 * 60 * 24) >= 3 &&
  progreso_modulo < 30
) {
  status_modulo = 'EN_RIESGO';
  en_riesgo = true;
}

// ✅ status_area: en este nodo no se puede recalcular el área completa (requiere TODOS los módulos del área),
// así que lo tomamos del evento si viene; si no, lo dejamos vacío.
const status_area = ev.status_area || ev.area_status || '';

return [{
  json: {
    employee_id: ev.employee_id || ev.empleado_id,
    email: ev.email || '',
    area_id: ev.area_id,
    modulo_id: ev.modulo_id,
    modulo_nombre: ev.modulo_nombre || '',
    // (opcional) dejo los anteriores por compatibilidad, si ya los usas en otros nodos
    progreso_area: progreso_modulo,
    status: status_modulo,
    recursos_total: total,
    recursos_completados: completados,
    last_activity_at,
    en_riesgo,
    updated_at: new Date().toISOString()
  }
}];

// Recalcula progreso del MÓDULO usando Empleado_Recursos_Progreso (filas del módulo)
// INPUT: items vienen desde "Read Empleado_Recursos_Progreso1" (returnAllMatches)
// WEBHOOK: datos del evento vienen de "Webhook - Update Topic Progress"

const ev = $items('Webhook - Update Topic Progress', 0, 0)[0].json.body || {};

// filas del módulo (cada item es un recurso del módulo)
const rows = $input.all().map(i => i.json);

