  return bytes;
}

async function pbkdf2Verify(password, stored) {
  const parts = stored.split("$");
  if (parts.length !== 5) throw new Error("Formato de hash inválido");
  const [, , iterStr, b64Salt, b64Hash] = parts;
  const iterations   = parseInt(iterStr, 10);
  const salt         = base64ToBytes(b64Salt);
  const expectedHash = base64ToBytes(b64Hash);

  const keyMaterial = await crypto.subtle.importKey(
    "raw", new TextEncoder().encode(password),
    { name: "PBKDF2" }, false, ["deriveBits"]
  );
  const derivedBits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt, iterations, hash: "SHA-256" },
    keyMaterial, expectedHash.length * 8
  );
  const derived = new Uint8Array(derivedBits);
  if (derived.length !== expectedHash.length) return false;
  let diff = 0;
  for (let i = 0; i < derived.length; i++) diff |= derived[i] ^ expectedHash[i];
  return diff === 0;
}

