// helpers
const toAreas = (v) => {
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  return String(v || "").split(",").map(x => x.trim()).filter(Boolean);
};
const uniqSort = (arr) => Array.from(new Set(arr)).sort();

// Áreas actuales (hoja)
const oldAreas = uniqSort(toAreas(current.area));
const area_actual = String(current.area || "").trim(); // <- tal cual hoja (ej: "OPERACIONES")

// Áreas entrantes (request)
