const ctx = $('Resolve Employee Context').item.json;
const moduleRows = $('Read Module Progress').all().map(i => i.json);
const resourceRows = $('Read Resource Progress').all().map(i => i.json);

const toNum = (v, fallback = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

const normalizeStatus = (status, pct) => {
  const s = String(status || '').toUpperCase();
  if (s === 'BLOQUEADO') return 'BLOQUEADO';
  if (pct >= 100 || s === 'COMPLETADO') return 'COMPLETADO';
  if (pct > 0 || s === 'EN_PROGRESO') return 'EN_PROGRESO';
  return 'NO_INICIADO';
};

const modules = moduleRows.map((row) => {
  const pct = toNum(row.completed_at, toNum(row.progreso_pct, 0));
  return {
    modulo_id: String(row.modulo_id || '').trim(),
    area_id: String(row.area_id || '').trim(),
    status: normalizeStatus(row.status, pct),
    completed_at: pct,
    last_activity_at: row.last_activity_at || ''
  };
}).filter(m => !!m.modulo_id);

const resources = resourceRows.map((row) => {
  const pct = toNum(row.completed_at, 0);
  const status = String(row.status || '').toUpperCase();
  return {
    modulo_id: String(row.modulo_id || '').trim(),
    topic_id: String(row.topic_id || '').trim(),
    recurso_id: String(row.recurso_id || '').trim(),
    status: status || normalizeStatus(status, pct),
    completed_at: pct,
    last_activity_at: row.last_activity_at || ''
  };
}).filter(r => !!r.recurso_id);

const areaAgg = new Map();
for (const m of modules) {
  if (!m.area_id) continue;
  const prev = areaAgg.get(m.area_id) || { sum: 0, count: 0, last_activity_at: '', max_status: 'NO_INICIADO' };
  prev.sum += m.completed_at;
  prev.count += 1;
  if (!prev.last_activity_at || String(m.last_activity_at || '') > String(prev.last_activity_at)) {
    prev.last_activity_at = m.last_activity_at || prev.last_activity_at;
  }
  if (m.status === 'BLOQUEADO') prev.max_status = 'BLOQUEADO';
  else if (m.status === 'COMPLETADO' && prev.max_status !== 'BLOQUEADO') prev.max_status = 'EN_PROGRESO';
  else if (m.status === 'EN_PROGRESO' && !['BLOQUEADO'].includes(prev.max_status)) prev.max_status = 'EN_PROGRESO';
  areaAgg.set(m.area_id, prev);
}

const areas = Array.from(areaAgg.entries()).map(([area_id, agg]) => {
  const pct = agg.count > 0 ? Math.round(agg.sum / agg.count) : 0;
  const status = normalizeStatus(agg.max_status, pct);
  return {
    area_id,
    status,
    completed_at: pct,
    last_activity_at: agg.last_activity_at || ''
  };
});

const modules_total = modules.length;
const modules_completed = modules.filter(m => m.completed_at >= 100).length;
const modules_in_progress = modules.filter(m => m.completed_at > 0 && m.completed_at < 100).length;
const global_progress_pct = modules_total > 0
  ? Math.round(modules.reduce((sum, m) => sum + m.completed_at, 0) / modules_total)
  : 0;

return [{
  json: {
    employee_id: ctx.employee_id,
    email: ctx.email,
    generated_at: ctx.generated_at,
    profile: {
      nombre: ctx.nombre,
      area: ctx.area,
      cohort: ctx.cohort,
      last_activity_at: ctx.last_activity_at
    },
    global: {
      progress_pct: global_progress_pct,
      modules_total,
      modules_completed,
      modules_in_progress
    },
    areas,
    modules,
    resources
  }
}];
